import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Returns priority with which we want to add item to each bin.
    Args:
        item: Size of item to be added to the bin.
        bins: Array of capacities for each bin.
    Return:
        Array of same size as bins with priority score of each bin."""
    if bins is None:
        return np.asarray([], dtype=np.float64)
    original_shape = np.asarray(bins).shape
    arr = np.asarray(bins, dtype=np.float64)
    if arr.size == 0:
        return arr.copy()
    item_f = float(item)
    if item_f <= 0.0:
        return (-arr).reshape(original_shape)
    gap = arr - item_f
    gap = np.where(gap < 0.0, 0.0, gap)
    best_fit = 1.0 / (1.0 + gap)
    mod = gap % item_f
    dist = np.minimum(mod, item_f - mod)
    mod_score = -dist
    scores = best_fit + mod_score
    exact = gap <= 1e-09
    if np.any(exact):
        scores = scores.copy()
        scores[exact] = scores[exact] + 1000.0
    return scores.reshape(original_shape)

import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Returns priority with which we want to add item to each bin.
    Args:
        item: Size of item to be added to the bin.
        bins: Array of capacities for each bin.
    Return:
        Array of same size as bins with priority score of each bin."""
    if bins is None:
        return np.asarray([], dtype=np.float64)
    original_shape = np.asarray(bins).shape
    arr = np.asarray(bins, dtype=np.float64)
    if arr.size == 0:
        return arr.copy()
    item_f = float(item)
    if item_f <= 0.0:
        return (-arr).reshape(original_shape)
    gap = arr - item_f
    gap = np.where(gap < 0.0, 0.0, gap)
    best_fit = 1.0 / (1.0 + 0.5 * gap / item_f)
    if item_f > 0:
        mod = gap % item_f
        dist = np.minimum(mod, item_f - mod)
        reuse_bonus = item_f * np.exp(-dist / (0.1 * item_f))
    else:
        reuse_bonus = np.zeros_like(gap)
    penalty = np.zeros_like(gap)
    dead = (gap > 0.0) & (gap < 0.5 * item_f)
    penalty[dead] = -0.3 * item_f / (1.0 + 0.5 * gap[dead] / item_f)
    scores = best_fit + 0.1 * reuse_bonus + penalty
    exact = gap <= 1e-09
    if np.any(exact):
        scores = scores.copy()
        scores[exact] = scores[exact] + 1000.0
    return scores.reshape(original_shape)
